import { AuthType, EmbedConfig } from '@thoughtspot/visual-embed-sdk';

/** ThoughtSpot worksheet / model GUID for Search, Spotter (Intellica), and Explore embeds */
export const THOUGHTSPOT_MODEL_ID = 'bc7ff5fa-f1cd-440a-a8d8-0a839bb18172';

/** Liveboard GUID for LiveboardEmbed (saved dashboard) */
export const THOUGHTSPOT_LIVEBOARD_ID = 'f3183f58-deec-4f2c-a6af-dc28b93608da';

/** ThoughtSpot Cloud cluster origin (no trailing slash) */
export const thoughtSpotHost = 'https://redflag.thoughtspot.cloud';

/**
 * SDK init — swap credentials for accounts on the RedFlag cluster.
 */
export function buildThoughtSpotEmbedConfig(): EmbedConfig {
  return {
    thoughtSpotHost,
    authType: AuthType.Basic,
    username: 'katie.matkin@thoughtspot.com',
    password: 'Sheffield.1!',
    suppressSearchEmbedBetaWarning: true,
    customizations: {
      content: {
        strings: {
          Spotter: 'Intellica',
          'AI Highlights': 'Highlights',
          Pin: 'Pin',
        },
      },
    },
  };
}
